/** The preview user + their build, or null (callers answer 404 — the feature doesn't exist for anyone else). */
export async function ownedBuild(id: string) {
  const user = await modBuilderUser();
  if (!user) return null;
  const build = await cyrusDb.modBuild.findUnique({ where: { id } });
  if (!build || build.userId !== user.id) return null;
  return { user, build };
}
