const NOT_FOUND = () => NextResponse.json({ error: "Not found" }, { status: 404, headers: { "x-robots-tag": "noindex" } });
const str = (v: unknown, max: number) => (typeof v === "string" ? v.slice(0, max) : "");

/** Only well-formed user-added games get through; everything is clamped (handoff, unchanged). */
function cleanGames(input: unknown): Game[] {
  if (!Array.isArray(input)) return [];
  return input
    .slice(0, MAX_GAMES)
    .filter((g) => g && typeof g === "object" && typeof g.id === "string" && g.id.startsWith("custom-"))
    .map((g) => {
      const template = TEMPLATES.find((t) => t.key === g.template) ?? TEMPLATES[0];
      // older clients may still hold v5 archetype keys ("worlds", "mechanics"): normalise them
      const categories: CyrusCategoryId[] = [...new Set((Array.isArray(g.categories) ? (g.categories as unknown[]) : []).map(normalizeCategory).filter((c): c is CyrusCategoryId => !!c && c in CATEGORY_BY_KEY))].slice(0, 6);
      return {
        id: str(g.id, 80),
        name: str(g.name, 40) || "Custom game",
        short: str(g.short, 16) || "Custom",
        toolchain: str(g.toolchain, 40) || template.toolchain,
        language: template.language,
        rgb: /^\d{1,3} \d{1,3} \d{1,3}$/.test(g.rgb) ? g.rgb : "167 139 250",
        emblem: EMBLEMS.includes(g.emblem) ? g.emblem : "cube",
        blurb: str(g.blurb, 120),
        aliases: (Array.isArray(g.aliases) ? g.aliases : []).map((a: unknown) => str(a, 40).toLowerCase()).filter(Boolean).slice(0, 6),
        categories: categories.length ? categories : ["gameplay"],
        template: template.key,
        custom: true,
      } satisfies Game;
    });
}

function ndjson(gen: (signal: AbortSignal) => AsyncGenerator<GenEvent>, req: Request) {
  const encoder = new TextEncoder();
  const abort = new AbortController();
  req.signal.addEventListener("abort", () => abort.abort());
  const stream = new ReadableStream<Uint8Array>({
    async start(controller) {
      try {
        for await (const event of gen(abort.signal)) controller.enqueue(encoder.encode(JSON.stringify(event) + "\n"));
      } catch (err) {
        if (!abort.signal.aborted) {
          console.error("[cyrus] forge stream", (err as Error).message);
          controller.enqueue(encoder.encode(JSON.stringify({ type: "error", message: "The forge lost its connection. Your build keeps going: it appears in the network when it's ready." }) + "\n"));
        }
      } finally {
        try { controller.close(); } catch { /* closed by a client abort */ }
      }
    },
    cancel() { abort.abort(); },
  });
  return new Response(stream, {
    headers: {
      "Content-Type": "application/x-ndjson; charset=utf-8",
      // no-transform keeps gzip from buffering the stream; nginx must not buffer it either.
      "Cache-Control": "no-cache, no-transform",
      "X-Accel-Buffering": "no",
    },
  });
}

/** The version a change builds on: the restored head, else the newest version that built. */
async function headOf(userId: string, rootId: string): Promise<string | null> {
  const rows = await cyrusDb.modBuild.findMany({ where: { userId, OR: [{ id: rootId }, { rootBuildId: rootId }] }, orderBy: { createdAt: "asc" } });
  const root = rows.find((r) => r.id === rootId);
  if (!root) return null;
  const ok = rows.filter((r) => r.status === "succeeded");
  const want = readCyrusMeta(root.cyrus).headBuildId;
  return (want && ok.find((r) => r.id === want)?.id) || ok[ok.length - 1]?.id || null;
}

