export const CYRUS_STUDIO_PUBLIC_FLAG = "cyrus_studio_public_enabled";

export { studioDecision } from "./studio-decision";
import { studioDecision } from "./studio-decision";

/** The public launch flag. Fails CLOSED: a settings/DB error never opens the studio. */
export async function studioPublicEnabled(): Promise<boolean> {
  try {
    return await getSettingBool(CYRUS_STUDIO_PUBLIC_FLAG, false);
  } catch {
    return false;
  }
}

/**
 * The public may build only when the studio flag AND the token economy are both on (lib/cyrus/launch-state.ts).
 * Fails CLOSED on any settings/DB error.
 */
export async function studioPublicEffective(): Promise<boolean> {
  try {
    const [studioPublic, tokensLive] = await Promise.all([getSettingBool(CYRUS_STUDIO_PUBLIC_FLAG, false), getSettingBool("cyrus_tok_live", false)]);
    return publicMayBuild({ studioPublic, tokensLive });
  } catch {
    return false;
  }
}

export async function modBuilderUser(): Promise<User | null> {
  const [user, real] = await Promise.all([currentUser(), realUser()]);
  if (!user || !real || user.id !== real.id) return null;
  return modBuilderAccess(user);
}

/** The access rule alone, for an account that is not the session (Cyrus API v1 subject). Same decision as modBuilderUser. */
export async function modBuilderAccess(user: User): Promise<User | null> {
  // r40: a suspended Nxeon account (e.g. a Cyrus ban propagated to Nxeon) never acts through Cyrus, not even as an
  // API v1 subject (no session, so realUser()'s own suspended check does not run on that path). Fails closed.
  if (user.suspended) return null;
  const previewUser = await isPreviewUser(user, "modbuilder");
  const publicOn = previewUser ? false : await studioPublicEffective();
  return studioDecision({ previewUser, publicOn, emailVerified: !!user.emailVerifiedAt }) ? user : null;
}

/**
 * STRICT private preview only (never opened by the public launch): the old Mod Builder UI and anything else
 * that must stay owner-only after Cyrus goes public.
 */
export async function modBuilderPreviewUser(): Promise<User | null> {

  const refineTemplate = !!ctx.modId && !refineReal;
  const route = refineReal || refineTemplate ? null : routePrompt(prompt, ctx, [...GAMES, ...body.games]);
  const real = refineReal || !!(route && GAME_BY_ID[route.gameId]?.real);

  if (real) {
    let baseBuildId: string | null = null;
    if (refineReal) {
      baseBuildId = await headOf(user.id, rootOfRealMod(ctx.modId!));
      if (!baseBuildId) return NextResponse.json({ error: "This mod has no version that built yet. Forge it again, or wait for the running build." }, { status: 400 });
    }
    const r = await createModBuild(user, {
      ...(baseBuildId ? { baseBuildId, changeRequest: prompt } : { prompt }),
      ...(typeof body.mcVersion === "string" ? { mcVersion: body.mcVersion } : {}),
      // Cyrus lifecycle: "Update with Cyrus for the new version" rebuilds the mod for mcVersion.
      ...(refineReal && body.retarget === true ? { retarget: true } : {}),
      model: body.model,
      attachmentIds: body.attachmentIds,
      // Cyrus R1: a REQUEST for custom assets (["texture"]); the server-side plan gate decides (lib/cyrus/assets/request.ts).
      // Live-test fix (F): or the plan screen's approved lanes ({ plan: 1, lanes }), with planAck once the user pressed
      // "Continue anyway" for lanes that cannot be built here (nothing is held before that).
      ...(body.assets !== undefined ? { assets: body.assets } : {}),
      ...(body.planAck === true ? { planAck: true } : {}),
      ...(body.plannerSource === "planner" ? { plannerSource: "planner" } : {}),
      // Cyrus starter bank (CYRUS_STARTER_BANK): the ready-made mod picked on the plan screen (re-matched server side)
      ...(!refineReal && body.bank && typeof body.bank === "object" ? { bank: body.bank } : {}),
    }, { requirePlanAck: true });
    if (!r.ok) return r.status === 404 ? NOT_FOUND() : NextResponse.json(r.json, { status: r.status });
    return ndjson((signal) => followBuild(r.build.id, { userId: user.id, refining: refineReal, signal }), req);
  }

  // NO BUILDER for this game yet. The handoff's template generator used to run here and hand back a made-up mod for a game
  // Cyrus cannot build for; that is not what a customer expects from a studio, so it is switched off. The studio shows the
  // game as "coming soon" and the dock refuses before this point; this is the server-side backstop.
  const named = (route && [...GAMES, ...body.games].find((g) => g.id === route.gameId)?.name) || ([...GAMES, ...body.games].find((g) => g.id === ctx.gameId)?.name) || "That game";
  return NextResponse.json({ error: `${named} support is coming soon. Cyrus builds Minecraft plugins today, and nothing was built or charged.`, code: "game_not_ready" }, { status: 409 });
  // eslint-disable-next-line no-unreachable
  return ndjson(async function* (signal) {
    for await (const ev of forgeStream(body as ForgeRequest, signal)) yield ev.type === "start" ? { ...ev, credits: 0, real: false } : ev;
  }, req);
}

export async function GET(req: Request) {
  const user = await modBuilderUser();
  if (!user) return NOT_FOUND();
  const id = new URL(req.url).searchParams.get("follow") || "";
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(id)) return NextResponse.json({ error: "Bad build id" }, { status: 400 });
  const row = await cyrusDb.modBuild.findUnique({ where: { id } });
  if (!row || row.userId !== user.id) return NOT_FOUND();
  return ndjson((signal) => followBuild(id, { userId: user.id, refining: !!row.baseBuildId, signal }), req);
}

import { NextResponse } from "next/server";
import { modBuilderUser } from "@/lib/modbuilder/access";
import { NOT_FOUND } from "@/app/api/mod-builder/_lib";
import { checkRateLimit } from "@/lib/rate-limit";
import { checkAuxAi } from "@/lib/cyrus/ai-aux-limits";
import { promptProblem } from "@/lib/cyrus/prompt-check";
import { MB_VERSIONS } from "@/lib/modbuilder/types";
import { getVersion } from "@/lib/cyrus/versions/registry";
import { analyzeNeeds, buildModPlan, type PlannerDeps } from "@/lib/cyrus/planner/run";
import { isLane, type Lane } from "@/lib/cyrus/planner/lanes";
import { svcHealthCached, svcHealthFresh, svcPlan } from "@/lib/cyrus/builder/client";
import { capacityUiOn } from "@/lib/cyrus/builder/capacity";
import { planCapacity } from "@/lib/cyrus/builder/queue-view";
import { tierOf, tokensActiveFor } from "@/lib/cyrus/tokens/access";
import { loadTokenConfig } from "@/lib/cyrus/tokens/config";
import { coachOn } from "@/lib/cyrus/coach/flags";
import { analyzePrompt } from "@/lib/cyrus/coach/analyze";
import { techniquesOn } from "@/lib/cyrus/designer/spec";
import { changeLaneDefaults, parseChangeContext } from "@/lib/cyrus/coach/plan-hook";
import { bankOn } from "@/lib/cyrus/bank/flag";
import { bankOffer } from "@/lib/cyrus/bank/plan";
import { serviceBankEntries } from "@/lib/cyrus/bank/service";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * Cyrus mod planner (live-test fix F): the pre-build PLAN for the plan screen. POST { prompt, mcVersion, change?, toggles? }
 * -> lanes (build / skip / blocked with plain warnings), what will be created, cost / time / tokens per model and the
 * Auto model. Nothing is held or charged here; the planner model call (~$0.001) is Nxeon's cost, rate-limited, and the
 * deterministic rules answer whenever it is unavailable. Same private-preview gate as the rest of Cyrus.
 * Prompt coach (CYRUS_PROMPT_COACH=1 only; off = this response is unchanged): adds `coach` (lib/cyrus/coach/analyze.ts,
 * deterministic, zero cost) and, on a change request, leaves out new generative lanes the change text does not ask for
 * (`coachHeld`; an explicit toggle always wins). Optional body field `base` = { name, version, summary, paths } of the
 * mod the change lands on (bounded; only feeds the "what will be kept" lines).
 * Starter bank (CYRUS_STARTER_BANK=1 only): adds `bank` = the ready-made answer (lib/cyrus/bank/plan.ts), when one matches and
 * the build service serves it; the plan screen shows "ready-made (instant)" next to "built by AI" with both estimates.
 * Capacity (CYRUS_CAPACITY_UI=1 only; off = no `capacity` field): the builder's queue right now and the measured wait for a
 * new build (lib/cyrus/builder/queue-view.ts planCapacity), from /health at most 10 s old. Never a made-up number.
 */
export async function POST(req: Request) {
  const user = await modBuilderUser();
  if (!user) return NOT_FOUND();
  let body: { prompt?: unknown; mcVersion?: unknown; change?: unknown; toggles?: unknown; game?: unknown; base?: unknown };
  try { body = (await req.json()) as typeof body; } catch { return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 }); }
  const prompt = typeof body.prompt === "string" ? body.prompt.trim().slice(0, 4000) : "";
  if (prompt.length < 4) return NextResponse.json({ error: "Describe the mod first." }, { status: 400 });
  const unclear = promptProblem(prompt);
  if (unclear) return NextResponse.json({ error: unclear, code: "prompt_unclear" }, { status: 400 });
  const mcVersion = typeof body.mcVersion === "string" && getVersion(body.mcVersion) ? body.mcVersion : MB_VERSIONS[0];
  const rl = checkRateLimit(`cy:plan:${user.id}`, { max: 30, windowMs: 60_000 });
  if (!rl.ok) return NextResponse.json({ error: `Planning fast! Try again in ${rl.retryAfterSec}s.` }, { status: 429 });
  // BQ-2: hour / day / global ceilings on the planner's model call (the minute limit alone is unbounded spend)
  const aux = checkAuxAi("plan", user.id);
  if (!aux.ok) return NextResponse.json({ error: aux.scope === "global" ? "Planning is busy right now. Try again in a little while." : `Planning a lot! Try again in ${Math.ceil(aux.retryAfterSec / 60)} min.` }, { status: 429 });
  const toggles: Partial<Record<Lane, boolean>> = {};
  if (body.toggles && typeof body.toggles === "object" && !Array.isArray(body.toggles)) for (const [k, v] of Object.entries(body.toggles as Record<string, unknown>)) if (isLane(k) && typeof v === "boolean") toggles[k] = v;
  const cfg = await loadTokenConfig().catch(() => null);
  const metered = cfg ? await tokensActiveFor(user, cfg).catch(() => false) : false;
  const tier = await tierOf(user.id, cfg ?? undefined).catch(() => null);
  const deps: PlannerDeps = { ask: (b) => svcPlan(b), supports: async () => ((await svcHealthCached())?.features as { planner?: unknown } | undefined)?.planner === true };
  const change = body.change === true;
  const coach = coachOn();
  // Coach hook (change requests): never pre-select a new generative lane the change text does not ask for.
  let held: Lane[] = [];
  let pre: Awaited<ReturnType<typeof analyzeNeeds>> | null = null;
  if (coach && change) {
    pre = await analyzeNeeds({ text: prompt, game: "minecraft", mcVersion }, deps);
    held = changeLaneDefaults(prompt, pre.lanes, toggles);
    for (const l of held) toggles[l] = false;
  }
  const out = await buildModPlan(
    { text: prompt, game: "minecraft", mcVersion, tier, change, toggles, cfg: metered ? cfg : null, ...(pre ? { needs: pre.lanes, source: pre.source, meta: { costUsd: pre.costUsd, ms: pre.ms, error: pre.error } } : {}) },
    deps,
  );
  const buildable = !!getVersion(mcVersion)?.buildable;
  // Cyrus starter bank (CYRUS_STARTER_BANK=1 only; off = no `bank` field): a ready-made answer, shown next to the AI estimate.
  const bank = bankOn() && !change ? bankOffer(prompt, mcVersion, { served: await serviceBankEntries().catch(() => new Map()), tokens: metered && cfg ? cfg.bankCharge : null }) : null;
  const extra = bank ? { bank } : {};
  // Cyrus capacity (CYRUS_CAPACITY_UI only; off = nothing added): the builder's queue right now
  const capacity = capacityUiOn() ? planCapacity((await svcHealthFresh().catch(() => null)) as Parameters<typeof planCapacity>[0]) : null;
  if (capacity) Object.assign(extra, { capacity });
  if (!coach) return NextResponse.json({ ...out, buildable, ...extra }, { headers: { "Cache-Control": "no-store" } });
  const base = change ? (parseChangeContext(body.base) ?? { name: "this mod" }) : null;
  const report = analyzePrompt({ text: prompt, version: mcVersion, change: base, lanes: out.plan.lanes, held, techniques: techniquesOn() });
  return NextResponse.json({ ...out, buildable, ...extra, coach: report, coachHeld: held }, { headers: { "Cache-Control": "no-store" } });
}
