      { text: prompt, draft, mcVersion, change: ch },
      { ask: (b) => svcCoach(b), supports: async () => ((await svcHealthCached())?.features as { coach?: unknown } | undefined)?.coach === true },
    );
    void recordCoachEvent({ userId: user.id, kind: out.source === "model" ? "rewrite" : "rewrite_failed", requestKind: ch ? "change" : "new", game: "minecraft", mcVersion, prompt, rewriteUsd: out.costUsd });
    return NextResponse.json(out, { headers: { "Cache-Control": "no-store" } });
  }

  if (body.mode === "event") {
    if (!isCoachEventKind(body.kind) || body.kind === "rewrite" || body.kind === "rewrite_failed") return NextResponse.json({ error: "Unknown event" }, { status: 400 });
    if (!prompt) return NextResponse.json({ error: "Missing prompt" }, { status: 400 });
    const rl = checkRateLimit(`cy:coach-ev:${user.id}`, { max: 60, windowMs: 60_000 });
    if (!rl.ok) return NextResponse.json({ ok: false }, { status: 429 });
    const num = (v: unknown) => (typeof v === "number" ? v : null);
    const ok = await recordCoachEvent({
      userId: user.id, kind: body.kind, requestKind: body.requestKind === "change" ? "change" : "new", game: "minecraft", mcVersion, prompt,
      archetype: typeof body.archetype === "string" ? body.archetype : null, scoreBefore: num(body.scoreBefore), scoreAfter: num(body.scoreAfter),
      level: typeof body.level === "string" ? body.level : null, gaps: Array.isArray(body.gaps) ? (body.gaps as unknown[]).filter((g): g is string => typeof g === "string") : null,
    });
