  if (!gate.ok) return fail(gate.status, { error: gate.error, code: gate.code, need: gate.need, available: gate.available, model: gate.model });
  const cyrus: CyrusMeta = { ...(gate.model ? { model: gate.model } : {}), bank: { id: m.id, version: m.version, via: m.via } };
  await cyrusDb.modBuild.create({ data: { id, userId: user.id, prompt: i.prompt, changeRequest: null, baseBuildId: null, rootBuildId: id, mcVersion: i.mcVersion, pluginName: null, cyrus } });
  try {
    await svcCreate({ id, prompt: i.prompt, mcVersion: i.mcVersion, bank: { id: m.id, params: m.params }, priority: "interactive", account: accountKey(user.id) });
  } catch (e) {
    const msg = e instanceof ModBuilderUnavailable ? "The builder is offline right now. Please try again in a few minutes." : "The builder couldn't take this request. Please try again.";
    const busy = e instanceof ModBuilderBusy ? busyFailure(e) : null;
    await cyrusDb.modBuild.update({ where: { id }, data: { status: "failed", errorCode: busy ? busy.errorCode : "unavailable", error: busy ? busy.error : msg, finishedAt: new Date() } });
    if (gate.tracked) await releaseBuildTokens(id);
    console.error("[modbuilder] bank create failed", id, (e as Error).message);
  }
  await db.auditLog.create({ data: { userId: user.id, action: "modbuilder.build", detail: `${id} bank:${m.id}` } }).catch(() => {});
  const fresh = await cyrusDb.modBuild.findUnique({ where: { id } });
