// Owner QA batch (2026-10-14): drives N prompts through the REAL portal build path as one account, serially, and records
// everything. Same functions the UI route app/api/cyrus/generate calls: planner (buildModPlan via the build service), coach
// analysis (deterministic), createModBuild (all gates: preview access, suspension, caps, token hold, plan ack).
// Usage (from the worktree, env from /opt/nxeon/.env):
//   NODE_PATH=/opt/nxeon/node_modules npx tsx scripts/cyrus/qa-owner-batch.ts run --user <userId> --out <dir> [--max 20] [--spacing 22] [--in-flight 2] [--spend-cap 8000] [--floor 3000]
//   ... collect --out <dir>      writes <dir>/records.json (+ prints table); safe to run repeatedly
import fs from "node:fs";
import path from "node:path";
import { cyrusDb } from "../../lib/cyrus/db";
import { db } from "../../lib/db";
import { modBuilderAccess } from "../../lib/modbuilder/access";
import { createModBuild } from "../../lib/modbuilder/create";
import { analyzeNeeds, buildModPlan, type PlannerDeps } from "../../lib/cyrus/planner/run";
import { svcHealthCached, svcPlan } from "../../lib/cyrus/builder/client";
import { analyzePrompt } from "../../lib/cyrus/coach/analyze";
import { coachOn } from "../../lib/cyrus/coach/flags";
import { techniquesOn } from "../../lib/cyrus/designer/spec";
import { tierOf, tokensActiveFor } from "../../lib/cyrus/tokens/access";
import { loadTokenConfig } from "../../lib/cyrus/tokens/config";
import { MB_VERSIONS } from "../../lib/modbuilder/types";

const argv = process.argv.slice(2);
const cmd = argv[0];
const opt = (n: string, d = "") => { const i = argv.indexOf(`--${n}`); return i >= 0 ? argv[i + 1] : d; };
const out = opt("out");
if (!out) throw new Error("--out required");
fs.mkdirSync(out, { recursive: true });
const journalPath = path.join(out, "journal.json");
type J = { key: string; prompt: string; buildId: string | null; submittedAt: string | null; plan?: unknown; coach?: unknown; refused?: unknown; heldTokens?: number };
const readJ = (): J[] => (fs.existsSync(journalPath) ? JSON.parse(fs.readFileSync(journalPath, "utf8")) : []);
const writeJ = (j: J[]) => fs.writeFileSync(journalPath, JSON.stringify(j, null, 1));
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const TERMINAL = ["succeeded", "failed"];

async function available(userId: string) {
  const a = await cyrusDb.cyrusTokenAccount.findUnique({ where: { userId } });
  return a ? a.balance - a.reserved : 0;
}

async function run() {
  const userId = opt("user");
  const max = Number(opt("max", "20")), spacing = Number(opt("spacing", "22")) * 1000, inflight = Number(opt("in-flight", "2"));
  const cap = Number(opt("spend-cap", "8000")), floor = Number(opt("floor", "3000"));
  const user = await db.user.findUnique({ where: { id: userId } });
  if (!user) throw new Error("no such user");
  if (!(await modBuilderAccess(user))) throw new Error("user has no Cyrus access (real gate)");
  const corpus: { key: string; prompt: string }[] = JSON.parse(fs.readFileSync(path.join(__dirname, "qa-owner-batch-prompts.json"), "utf8")).slice(0, max);
  const journal = readJ();
  const start = journal.length ? Number((journal as unknown as { startAvail?: number }[])[0]?.startAvail ?? 0) : 0;
  const startAvail = (journal as unknown as { startAvail?: number }[])[0]?.startAvail ?? (await available(userId));
  const mcVersion = MB_VERSIONS[0];
  const cfg = await loadTokenConfig().catch(() => null);
  const metered = cfg ? await tokensActiveFor(user, cfg).catch(() => false) : false;
  const tier = await tierOf(userId, cfg ?? undefined).catch(() => null);
  const deps: PlannerDeps = { ask: (b) => svcPlan(b), supports: async () => ((await svcHealthCached())?.features as { planner?: unknown } | undefined)?.planner === true };
  console.log(`user ${userId} start available ${startAvail} version ${mcVersion} tier ${tier} metered ${metered} coach ${coachOn()}`);
  for (const item of corpus) {
    if (journal.find((j) => j.key === item.key)) continue;
    // concurrency gate
    for (;;) {
      const live = await cyrusDb.modBuild.count({ where: { userId, status: { notIn: TERMINAL } } });
      if (live < inflight) break;
      await sleep(15_000);
    }
    const av = await available(userId);
    if (av < floor) { console.log(`STOP: available ${av} < floor ${floor}`); break; }
    // spent-so-far = what left the available pool since start (settled spends + live holds)
    if (startAvail - av >= cap) { console.log(`STOP: spent ${startAvail - av} >= cap ${cap}`); break; }
    // 1) planner, exactly as POST /api/cyrus/plan
    const pre = await analyzeNeeds({ text: item.prompt, game: "minecraft", mcVersion }, deps);
    const plan = await buildModPlan({ text: item.prompt, game: "minecraft", mcVersion, tier, change: false, cfg: metered ? cfg : null, needs: pre.lanes, source: pre.source, meta: { costUsd: pre.costUsd, ms: pre.ms, error: pre.error } }, deps);
    const coach = coachOn() ? analyzePrompt({ text: item.prompt, version: mcVersion, change: null, lanes: plan.plan.lanes, held: [], techniques: techniquesOn() }) : null;
    // 2) generate, exactly as the plan screen posts it (model auto, approved lanes, plan ack)
    const body = { prompt: item.prompt, mcVersion, model: "auto", assets: plan.assets, plannerSource: plan.planner.source === "planner" ? "planner" : "rules", ...(plan.plan.mustConfirm ? { planAck: true } : {}) };
    const t0 = Date.now();
    const r = await createModBuild(user, body as Record<string, unknown>, { requirePlanAck: true });
    const row: J = { key: item.key, prompt: item.prompt, buildId: r.ok ? r.build.id : null, submittedAt: new Date(t0).toISOString(), plan: { lanes: plan.plan.lanes, mustConfirm: plan.plan.mustConfirm, source: plan.planner.source, plannerCostUsd: plan.planner.costUsd, auto: plan.auto, assets: plan.assets }, coach: coach ? { score: (coach as { score?: unknown }).score, level: (coach as { level?: unknown }).level, gaps: (coach as { gaps?: unknown }).gaps } : null };
    if (!r.ok) row.refused = { status: r.status, json: r.json };
    (row as unknown as { startAvail?: number }).startAvail = journal.length === 0 ? startAvail : undefined;
    journal.push(row);
    writeJ(journal);
    console.log(`${item.key}: ${r.ok ? r.build.id + " " + r.build.status : "REFUSED " + JSON.stringify(r.json).slice(0, 200)} avail ${await available(userId)}`);
    if (!r.ok && [402, 403, 503].includes(r.status)) { console.log("STOP: hard refusal"); break; }
    await sleep(spacing);
  }
  void start;
  console.log("all submitted; waiting for terminal states");
  for (;;) {
    const ids = readJ().map((j) => j.buildId).filter(Boolean) as string[];
    const live = await cyrusDb.modBuild.count({ where: { id: { in: ids }, status: { notIn: TERMINAL } } });
    if (!live) break;
    await sleep(30_000);
  }
  // let the worker's Test Flight finish (up to 15 min after the last build ends)
  const until = Date.now() + 15 * 60_000;
  while (Date.now() < until) {
    const ids = readJ().map((j) => j.buildId).filter(Boolean) as string[];
    const rows = await cyrusDb.modBuild.findMany({ where: { id: { in: ids }, status: "succeeded" }, select: { cyrus: true } });
    const open = rows.filter((x) => { const f = (x.cyrus as { testFlight?: { state?: string } } | null)?.testFlight; return !f || f.state === "queued" || f.state === "running"; });
    if (!open.length) break;
    await sleep(30_000);
  }
  await collect();
}

async function collect() {
  const j = readJ();
  const recs = [];
  for (const e of j) {
    const row = e.buildId ? await cyrusDb.modBuild.findUnique({ where: { id: e.buildId } }) : null;
    const res = (row?.result ?? {}) as Record<string, any>;
